CREATE TABLE public.sms_broadcasts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL, message text NOT NULL CHECK(length(message) BETWEEN 1 AND 480), audience text NOT NULL CHECK(audience IN ('all','recent','selected')), total integer NOT NULL DEFAULT 0, accepted integer NOT NULL DEFAULT 0, failed integer NOT NULL DEFAULT 0, skipped integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'processing', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.sms_broadcasts TO authenticated;
GRANT ALL ON public.sms_broadcasts TO service_role;
ALTER TABLE public.sms_broadcasts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read broadcasts" ON public.sms_broadcasts FOR SELECT TO authenticated USING(public.is_hr_admin(auth.uid()));
CREATE OR REPLACE FUNCTION public.validate_kazini_records() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='clients' THEN IF length(NEW.residential_address)>1000 OR length(NEW.special_requirements)>2000 OR length(NEW.comments)>2000 OR length(NEW.company_name)>150 OR length(NEW.industry)>150 OR length(NEW.signature)>150 OR length(NEW.emergency_name)>150 OR length(NEW.emergency_relationship)>150 OR NEW.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR (NEW.website<>'' AND NEW.website !~ '^https?://') THEN RAISE EXCEPTION 'Invalid client details'; END IF; ELSIF TG_TABLE_NAME='profiles' THEN IF length(trim(NEW.full_name)) NOT BETWEEN 2 AND 150 OR length(NEW.phone)>30 OR (NEW.avatar_path IS NOT NULL AND NEW.avatar_path NOT LIKE NEW.id::text || '/%') THEN RAISE EXCEPTION 'Invalid profile details'; END IF; ELSIF TG_TABLE_NAME='departments' THEN IF length(trim(NEW.name)) NOT BETWEEN 1 AND 150 OR length(trim(NEW.code)) NOT BETWEEN 1 AND 30 OR length(NEW.description)>2000 THEN RAISE EXCEPTION 'Invalid department details'; END IF; ELSIF TG_TABLE_NAME='employees' THEN IF length(trim(NEW.first_name)) NOT BETWEEN 1 AND 150 OR length(NEW.last_name)>150 OR length(NEW.employee_code)>40 OR NEW.salary<0 THEN RAISE EXCEPTION 'Invalid employee details'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_clients BEFORE INSERT OR UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION public.validate_kazini_records();
CREATE TRIGGER validate_profiles BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_kazini_records();
CREATE TRIGGER validate_departments BEFORE INSERT OR UPDATE ON public.departments FOR EACH ROW EXECUTE FUNCTION public.validate_kazini_records();
CREATE TRIGGER validate_employees BEFORE INSERT OR UPDATE ON public.employees FOR EACH ROW EXECUTE FUNCTION public.validate_kazini_records();
REVOKE EXECUTE ON FUNCTION public.validate_kazini_records() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.prevent_linked_department_delete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.employees WHERE department_id=OLD.id) OR EXISTS(SELECT 1 FROM public.positions WHERE department_id=OLD.id) OR EXISTS(SELECT 1 FROM public.announcements WHERE department_id=OLD.id) OR EXISTS(SELECT 1 FROM public.user_department_access WHERE department_id=OLD.id) THEN RAISE EXCEPTION 'Reassign linked records before deleting this department'; END IF; RETURN OLD; END; $$;
CREATE TRIGGER prevent_linked_department_delete BEFORE DELETE ON public.departments FOR EACH ROW EXECUTE FUNCTION public.prevent_linked_department_delete();
REVOKE EXECUTE ON FUNCTION public.prevent_linked_department_delete() FROM PUBLIC,anon,authenticated;